{
  "schemaVersion": "0.2",
  "slug": "time-picker",
  "name": "TimePicker",
  "family": "C",
  "status": "experimental",
  "purpose": "Picks a wall-clock time via hour and minute controls formatted with Intl.",
  "scenarios": [
    "Set a reminder time",
    "Schedule a publish slot",
    "Choose a meeting start"
  ],
  "props": {
    "value": {
      "type": "string",
      "required": true,
      "description": "Time string HH:mm or empty."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called with the HH:mm string on change."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Field label."
    },
    "hourLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the hour control."
    },
    "minuteLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the minute control."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Time controls rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "card",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not hand-pad time strings; use Intl-aware formatting helpers.",
    "Do not mix 12h and 24h presentation in one form."
  ],
  "a11y": {
    "role": "group",
    "keyboard": [
      "Arrow keys step values in the selects"
    ],
    "focus": "Hour and minute selects are in tab order.",
    "labeling": "Group label plus per-select labels describe the time.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Inline controls wrap on very narrow screens.",
    "breakpoints": {
      "compact": "Wrapped controls.",
      "medium": "Inline controls.",
      "large": "Inline controls."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "time-picker",
    "states": [
      "default"
    ],
    "intents": [
      "pick-datetime"
    ]
  }
}

.cu-time-picker {
  display: inline-flex;
  align-items: flex-end;
  gap: var(--cu-space-1);
  color: var(--cu-color-fg-default);
}

.cu-time-picker__field {
  display: flex;
  flex-direction: column;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-time-picker__label {
  font-size: 0.875em;
}

.cu-time-picker__select {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
}

.cu-time-picker__select:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-time-picker__separator {
  padding-block-end: var(--cu-space-2);
}

import './styles.css'

export interface TimePickerProps {
  value: string
  onChange: (value: string) => void
  label: string
  hourLabel?: string
  minuteLabel?: string
  locale?: string
  className?: string
}

function parseTime(value: string): { hour: number; minute: number } | null {
  const match = /^(\d{1,2}):(\d{2})$/.exec(value)
  if (!match) return null
  const hour = Number(match[1])
  const minute = Number(match[2])
  if (hour > 23 || minute > 59) return null
  return { hour, minute }
}

export function TimePicker({ value, onChange, label, hourLabel = 'Hour', minuteLabel = 'Minute', locale = 'en', className }: TimePickerProps) {
  const classes = ['cu-time-picker', className].filter(Boolean).join(' ')
  const parsed = parseTime(value)
  const numberFormat = new Intl.NumberFormat(locale, { minimumIntegerDigits: 2, useGrouping: false })

  const emit = (hour: number, minute: number) => {
    onChange(`${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`)
  }

  return (
    <div className={classes} role="group" aria-label={label} data-ai-role="time-picker" data-ai-intent="pick-datetime" data-ai-state="default">
      <label className="cu-time-picker__field">
        <span className="cu-time-picker__label">{hourLabel}</span>
        <select
          className="cu-time-picker__select"
          value={parsed?.hour ?? ''}
          onChange={(event) => emit(Number(event.currentTarget.value), parsed?.minute ?? 0)}
        >
          <option value="" disabled>
            --
          </option>
          {Array.from({ length: 24 }, (_, hour) => (
            <option key={hour} value={hour}>
              {numberFormat.format(hour)}
            </option>
          ))}
        </select>
      </label>
      <span className="cu-time-picker__separator" aria-hidden="true">
        :
      </span>
      <label className="cu-time-picker__field">
        <span className="cu-time-picker__label">{minuteLabel}</span>
        <select
          className="cu-time-picker__select"
          value={parsed?.minute ?? ''}
          onChange={(event) => emit(parsed?.hour ?? 0, Number(event.currentTarget.value))}
        >
          <option value="" disabled>
            --
          </option>
          {Array.from({ length: 60 }, (_, minute) => (
            <option key={minute} value={minute}>
              {numberFormat.format(minute)}
            </option>
          ))}
        </select>
      </label>
    </div>
  )
}
